draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw fish
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 60, H/2);
  ctx.lineTo(W/2 + 100, H/2 + 20);
  ctx.lineTo(W/2 + 60, H/2 + 40);
  ctx.stroke();

  // draw oil drops
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W/2 + 120 + i*20, H/2 + 20 + 20*Math.sin(t + i), 10, 0, 2*Math.PI);
    ctx.stroke();
  }

  // draw brain
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 30, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2);
  ctx.lineTo(W/2 - 130, H/2 + 20);
  ctx.lineTo(W/2 - 100, H/2 + 40);
  ctx.stroke();

  // draw heart
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 20);
  ctx.lineTo(W/2 - 70, H/2 + 50);
  ctx.lineTo(W/2 - 30, H/2 + 50);
  ctx.lineTo(W/2 - 50, H/2 + 20);
  ctx.stroke();

  ctx.restore();
}
